      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'light';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Chart colors ===
    var COLORS = { Communicable: '#C9544D', NCD: '#2B6998', Injury: '#E6A817' };

    // === ChartManager ===
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart init failed for ' + canvasId + ':', error); return null; }
      },
      destroyAll: function() {
        this.charts.forEach(function(chart) { try { chart.destroy(); } catch(e) {} });
        this.charts.clear();
      }
    };

    // === Data ===
    var globalData = [
      { year: 1990, category: 'Communicable', dalys: 1128.4 },
      { year: 1990, category: 'NCD', dalys: 768.2 },
      { year: 1990, category: 'Injury', dalys: 253.7 },
      { year: 2024, category: 'Communicable', dalys: 612.5 },
      { year: 2024, category: 'NCD', dalys: 1487.3 },
      { year: 2024, category: 'Injury', dalys: 308.6 }
    ];

    var incomeData = [
      { year: 1990, group: 'Low income', comm: 71.2, ncd: 19.8, inj: 9.0 },
      { year: 1990, group: 'Lower-middle', comm: 52.4, ncd: 36.1, inj: 11.5 },
      { year: 1990, group: 'Upper-middle', comm: 28.7, ncd: 57.3, inj: 14.0 },
      { year: 1990, group: 'High income', comm: 8.3, ncd: 81.6, inj: 10.1 },
      { year: 2024, group: 'Low income', comm: 52.8, ncd: 37.4, inj: 9.8 },
      { year: 2024, group: 'Lower-middle', comm: 27.1, ncd: 60.5, inj: 12.4 },
      { year: 2024, group: 'Upper-middle', comm: 11.3, ncd: 77.2, inj: 11.5 },
      { year: 2024, group: 'High income', comm: 4.1, ncd: 87.8, inj: 8.1 }
    ];

    var topCauses = {
      1990: [
        { rank: 1, cause: 'Lower respiratory infections', cat: 'Communicable', dalys: 178.5 },
        { rank: 2, cause: 'Diarrheal diseases', cat: 'Communicable', dalys: 155.2 },
        { rank: 3, cause: 'Neonatal preterm birth', cat: 'Communicable', dalys: 103.8 },
        { rank: 4, cause: 'Ischemic heart disease', cat: 'NCD', dalys: 98.6 },
        { rank: 5, cause: 'Stroke', cat: 'NCD', dalys: 82.4 },
        { rank: 6, cause: 'Malaria', cat: 'Communicable', dalys: 78.1 },
        { rank: 7, cause: 'Tuberculosis', cat: 'Communicable', dalys: 72.3 },
        { rank: 8, cause: 'Measles', cat: 'Communicable', dalys: 65.9 },
        { rank: 9, cause: 'COPD', cat: 'NCD', dalys: 57.2 },
        { rank: 10, cause: 'Road injuries', cat: 'Injury', dalys: 52.7 }
      ],
      2024: [
        { rank: 1, cause: 'Ischemic heart disease', cat: 'NCD', dalys: 192.3 },
        { rank: 2, cause: 'Stroke', cat: 'NCD', dalys: 147.8 },
        { rank: 3, cause: 'Diabetes mellitus', cat: 'NCD', dalys: 118.4 },
        { rank: 4, cause: 'COPD', cat: 'NCD', dalys: 105.1 },
        { rank: 5, cause: 'Neonatal preterm birth', cat: 'Communicable', dalys: 82.6 },
        { rank: 6, cause: 'Lower respiratory infections', cat: 'Communicable', dalys: 78.3 },
        { rank: 7, cause: 'Low back pain', cat: 'NCD', dalys: 74.9 },
        { rank: 8, cause: 'Depressive disorders', cat: 'NCD', dalys: 68.5 },
        { rank: 9, cause: 'Road injuries', cat: 'Injury', dalys: 63.2 },
        { rank: 10, cause: 'Lung cancer', cat: 'NCD', dalys: 58.7 }
      ]
    };

    // === Build Charts ===
    var chartsBuilt = false;

    function getThemeColors() {
      var s = getComputedStyle(document.documentElement);
      return {
        text: s.getPropertyValue('--text').trim(),
        textSecondary: s.getPropertyValue('--text-secondary').trim(),
        border: s.getPropertyValue('--border').trim(),
        surface: s.getPropertyValue('--surface').trim()
      };
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;
      var tc = getThemeColors();
      var gridColor = document.documentElement.classList.contains('theme-dark') ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';

      // Panel A: Global Structural Transition - Stacked Bar
      var global1990 = globalData.filter(function(d) { return d.year === 1990; });
      var global2024 = globalData.filter(function(d) { return d.year === 2024; });

      ChartManager.safeInit('chartGlobal', {
        type: 'bar',
        data: {
          labels: ['1990', '2024'],
          datasets: [
            {
              label: 'Communicable',
              data: [
                global1990.find(function(d) { return d.category === 'Communicable'; }).dalys,
                global2024.find(function(d) { return d.category === 'Communicable'; }).dalys
              ],
              backgroundColor: COLORS.Communicable,
              borderRadius: 2
            },
            {
              label: 'NCD',
              data: [
                global1990.find(function(d) { return d.category === 'NCD'; }).dalys,
                global2024.find(function(d) { return d.category === 'NCD'; }).dalys
              ],
              backgroundColor: COLORS.NCD,
              borderRadius: 2
            },
            {
              label: 'Injury',
              data: [
                global1990.find(function(d) { return d.category === 'Injury'; }).dalys,
                global2024.find(function(d) { return d.category === 'Injury'; }).dalys
              ],
              backgroundColor: COLORS.Injury,
              borderRadius: 2
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          plugins: {
            tooltip: { enabled: true, mode: 'index', intersect: false, padding: 12, cornerRadius: 8, callbacks: { label: function(ctx) { return ctx.dataset.label + ': ' + ctx.raw.toFixed(1) + 'M DALYs'; } } },
            legend: { display: false }
          },
          scales: {
            x: {
              stacked: true,
              ticks: { color: tc.textSecondary, font: { family: 'Inter', size: 13, weight: '600' } },
              grid: { display: false },
              border: { color: gridColor }
            },
            y: {
              stacked: true,
              title: { display: true, text: 'DALYs (millions)', color: tc.textSecondary, font: { family: 'Inter', size: 12 } },
              ticks: { color: tc.textSecondary, font: { family: 'Inter', size: 11 }, callback: function(v) { return v; } },
              grid: { color: gridColor },
              border: { color: gridColor }
            }
          },
          layout: { padding: { top: 10, right: 16, bottom: 4, left: 4 } }
        }
      });

      // Panel B: Income Group Disparity - 100% Stacked Horizontal Bar
      var incomeLabels = [
        'Low income (1990)', 'Low income (2024)',
        'Lower-middle (1990)', 'Lower-middle (2024)',
        'Upper-middle (1990)', 'Upper-middle (2024)',
        'High income (1990)', 'High income (2024)'
      ];
      var incomeComm = incomeData.map(function(d) { return d.comm; });
      var incomeNcd = incomeData.map(function(d) { return d.ncd; });
      var incomeInj = incomeData.map(function(d) { return d.inj; });

      ChartManager.safeInit('chartIncome', {
        type: 'bar',
        data: {
          labels: incomeLabels,
          datasets: [
            {
              label: 'Communicable',
              data: incomeComm,
              backgroundColor: COLORS.Communicable,
              borderRadius: 2
            },
            {
              label: 'NCD',
              data: incomeNcd,
              backgroundColor: COLORS.NCD,
              borderRadius: 2
            },
            {
              label: 'Injury',
              data: incomeInj,
              backgroundColor: COLORS.Injury,
              borderRadius: 2
            }
          ]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          plugins: {
            tooltip: { enabled: true, mode: 'index', intersect: false, padding: 12, cornerRadius: 8, callbacks: { label: function(ctx) { return ctx.dataset.label + ': ' + ctx.raw.toFixed(1) + '%'; } } },
            legend: { display: false }
          },
          scales: {
            x: {
              stacked: true,
              max: 100,
              title: { display: true, text: 'Share of total DALYs (%)', color: tc.textSecondary, font: { family: 'Inter', size: 12 } },
              ticks: { color: tc.textSecondary, font: { family: 'Inter', size: 11 }, callback: function(v) { return v + '%'; } },
              grid: { color: gridColor },
              border: { color: gridColor }
            },
            y: {
              stacked: true,
              ticks: { color: tc.textSecondary, font: { family: 'Inter', size: 10 } },
              grid: { display: false },
              border: { color: gridColor }
            }
          },
          layout: { padding: { top: 4, right: 16, bottom: 4, left: 4 } }
        }
      });

      // Panel C: Slope Chart (SVG-based)
      buildSlopeChart(tc, gridColor);

      chartsBuilt = true;
    }

    function buildSlopeChart(tc, gridColor) {
      var container = document.getElementById('slopeContainer');
      if (!container) return;
      var w = container.clientWidth;
      var h = container.clientHeight;
      if (w === 0 || h === 0) return;

      var padLeft = 180;
      var padRight = 180;
      var padTop = 20;
      var padBot = 20;
      var chartW = w - padLeft - padRight;
      var chartH = h - padTop - padBot;

      var causes1990 = {};
      var causes2024 = {};
      topCauses[1990].forEach(function(c) { causes1990[c.cause] = c; });
      topCauses[2024].forEach(function(c) { causes2024[c.cause] = c; });

      // All unique causes
      var allCauses = [];
      var seen = {};
      topCauses[1990].forEach(function(c) { if (!seen[c.cause]) { allCauses.push(c); seen[c.cause] = true; } });
      topCauses[2024].forEach(function(c) { if (!seen[c.cause]) { allCauses.push(c); seen[c.cause] = true; } });

      var textColor = tc.text || '#0f172a';
      var textSecColor = tc.textSecondary || '#64748b';
      var lineGridColor = gridColor || 'rgba(0,0,0,0.06)';

      var svg = '<svg width="' + w + '" height="' + h + '" xmlns="http://www.w3.org/2000/svg">';

      // Year labels
      svg += '<text x="' + padLeft + '" y="14" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="600">1990</text>';
      svg += '<text x="' + (padLeft + chartW) + '" y="14" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="600">2024</text>';

      // Rank lines (1-10)
      for (var i = 1; i <= 10; i++) {
        var yy = padTop + ((i - 1) / 9) * chartH;
        svg += '<line x1="' + padLeft + '" y1="' + yy + '" x2="' + (padLeft + chartW) + '" y2="' + yy + '" stroke="' + lineGridColor + '" stroke-width="1" stroke-dasharray="3,3"/>';
        // rank numbers on both sides
        svg += '<text x="' + (padLeft - 12) + '" y="' + (yy + 4) + '" text-anchor="end" fill="' + textSecColor + '" font-family="Inter" font-size="10">#' + i + '</text>';
        svg += '<text x="' + (padLeft + chartW + 12) + '" y="' + (yy + 4) + '" text-anchor="start" fill="' + textSecColor + '" font-family="Inter" font-size="10">#' + i + '</text>';
      }

      // Draw connecting lines and labels for causes in both years
      var connectedCauses = [];
      allCauses.forEach(function(c) {
        var in1990 = causes1990[c.cause];
        var in2024 = causes2024[c.cause];
        if (in1990 && in2024) {
          connectedCauses.push({ cause: c.cause, cat: c.cat, r1990: in1990.rank, r2024: in2024.rank, d1990: in1990.dalys, d2024: in2024.dalys });
        }
      });

      // Draw lines that EXIT (only in 1990) - faded
      allCauses.forEach(function(c) {
        var in1990 = causes1990[c.cause];
        var in2024 = causes2024[c.cause];
        if (in1990 && !in2024) {
          var y1990 = padTop + ((in1990.rank - 1) / 9) * chartH;
          var col = COLORS[in1990.cat];
          // Dashed line fading out to right
          svg += '<line x1="' + padLeft + '" y1="' + y1990 + '" x2="' + (padLeft + chartW * 0.65) + '" y2="' + (y1990 + (y1990 > chartH/2 + padTop ? 20 : -20)) + '" stroke="' + col + '" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.4"/>';
          svg += '<circle cx="' + padLeft + '" cy="' + y1990 + '" r="4" fill="' + col + '" stroke="white" stroke-width="1.5" opacity="0.5"/>';
          // Left label
          svg += '<text x="' + (padLeft - 16) + '" y="' + (y1990 + 4) + '" text-anchor="end" fill="' + col + '" font-family="Inter" font-size="11" opacity="0.6">' + in1990.cause + '</text>';
        }
      });

      // Draw lines that ENTER (only in 2024) - faded
      allCauses.forEach(function(c) {
        var in1990 = causes1990[c.cause];
        var in2024 = causes2024[c.cause];
        if (!in1990 && in2024) {
          var y2024 = padTop + ((in2024.rank - 1) / 9) * chartH;
          var col = COLORS[in2024.cat];
          // Dashed line fading in from left
          svg += '<line x1="' + (padLeft + chartW * 0.35) + '" y1="' + (y2024 + (y2024 > chartH/2 + padTop ? 20 : -20)) + '" x2="' + (padLeft + chartW) + '" y2="' + y2024 + '" stroke="' + col + '" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.4"/>';
          svg += '<circle cx="' + (padLeft + chartW) + '" cy="' + y2024 + '" r="4" fill="' + col + '" stroke="white" stroke-width="1.5" opacity="0.5"/>';
          // Right label
          svg += '<text x="' + (padLeft + chartW + 16) + '" y="' + (y2024 + 4) + '" text-anchor="start" fill="' + col + '" font-family="Inter" font-size="11" opacity="0.6">' + in2024.cause + '</text>';
        }
      });

      // Draw connected cause lines (bold, prominent)
      // Sort by rank change magnitude so most prominent lines are drawn on top
      connectedCauses.sort(function(a, b) { return Math.abs(b.r2024 - b.r1990) - Math.abs(a.r2024 - a.r1990); });

      connectedCauses.forEach(function(c) {
        var y1990 = padTop + ((c.r1990 - 1) / 9) * chartH;
        var y2024 = padTop + ((c.r2024 - 1) / 9) * chartH;
        var col = COLORS[c.cat];
        var rankChange = c.r1990 - c.r2024; // positive = rose, negative = dropped
        var lineOpacity = Math.min(1, 0.5 + Math.abs(rankChange) * 0.15);
        var lineW = Math.max(1.5, 1.5 + Math.abs(rankChange) * 0.4);

        svg += '<line x1="' + padLeft + '" y1="' + y1990 + '" x2="' + (padLeft + chartW) + '" y2="' + y2024 + '" stroke="' + col + '" stroke-width="' + lineW + '" opacity="' + lineOpacity + '"/>';

        // Dots
        svg += '<circle cx="' + padLeft + '" cy="' + y1990 + '" r="5" fill="' + col + '" stroke="white" stroke-width="1.5"/>';
        svg += '<circle cx="' + (padLeft + chartW) + '" cy="' + y2024 + '" r="5" fill="' + col + '" stroke="white" stroke-width="1.5"/>';

        // Left label (1990)
        var changeIndicator = '';
        if (rankChange > 0) changeIndicator = ' ↑' + rankChange;
        else if (rankChange < 0) changeIndicator = ' ↓' + Math.abs(rankChange);

        svg += '<text x="' + (padLeft - 16) + '" y="' + (y1990 + 4) + '" text-anchor="end" fill="' + col + '" font-family="Inter" font-size="11.5" font-weight="500">' + c.cause + '</text>';

        // Right label (2024) with rank change
        svg += '<text x="' + (padLeft + chartW + 16) + '" y="' + (y2024 + 4) + '" text-anchor="start" fill="' + col + '" font-family="Inter" font-size="11.5" font-weight="500">' + c.cause + '</text>';
        if (changeIndicator) {
          svg += '<tspan fill="' + (rankChange > 0 ? '#059669' : '#e11d48') + '" font-weight="600" font-size="10"> ' + changeIndicator.trim() + '</tspan>';
        }
      });

      svg += '</svg>';
      container.innerHTML = svg;
    }

    document.addEventListener('DOMContentLoaded', buildCharts);

    function onThemeChange() {
      chartsBuilt = false;
      ChartManager.destroyAll();
      setTimeout(buildCharts, 100);
    }

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = 'global-disease-burden-transition.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }
  </script>
</body>
</html>
