      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto 1fr;
      gap: 18px;
      height: calc(100% - 72px);
      margin-top: 18px;
    }

    .panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 18px 22px;
      overflow: hidden;
    }
    .panel-label {
      font-size: 10px; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.1em; color: var(--text-secondary); margin-bottom: 2px;
    }
    .panel h2 { font-size: 15px; margin-bottom: 10px; color: var(--text); }
    .panel-full { grid-column: 1 / -1; }

    .chart-area { position: relative; width: 100%; }

    @media print {
      body { background: white !important; color: black !important; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
  </style>
</head>
<body>
  <main id="main-content" role="main">
    <header style="display:flex; justify-content:space-between; align-items:flex-start;">
      <div>
        <h1 style="font-size:26px; margin-bottom:4px;">Global Disease Burden: The Epidemiological Transition, 1990–2024</h1>
        <p style="font-size:13px; color:var(--text-secondary);">DALYs by disease category — communicable diseases, non-communicable diseases (NCDs), and injuries | Source: GBD-style modeled estimates</p>
      </div>
      <div class="legend-bar" style="padding-top:6px;">
        <div class="legend-item"><div class="legend-dot" style="background:#C9544D"></div><span>Communicable, maternal, neonatal &amp; nutritional</span></div>
        <div class="legend-item"><div class="legend-dot" style="background:#2B6998"></div><span>Non-communicable diseases (NCDs)</span></div>
        <div class="legend-item"><div class="legend-dot" style="background:#E6A817"></div><span>Injuries</span></div>
      </div>
    </header>

    <div class="panel-grid">
      <!-- Panel A: Global Structural Transition -->
      <section class="panel" aria-label="Global DALY structural transition">
        <div class="panel-label">Panel A</div>
        <h2>Global DALY Burden Shift</h2>
        <div class="chart-area" id="chartA" style="height:330px;"></div>
      </section>

      <!-- Panel B: Income Group Disparity -->
      <section class="panel" aria-label="Income group disease burden composition">
        <div class="panel-label">Panel B</div>
        <h2>Burden Composition by World Bank Income Group</h2>
        <div class="chart-area" id="chartB" style="height:330px;"></div>
      </section>

      <!-- Panel C: Top Cause Rank Changes -->
      <section class="panel panel-full" aria-label="Top 10 DALY cause rank changes">
        <div class="panel-label">Panel C</div>
        <h2>Rank Changes of Top 10 DALY Causes, 1990 → 2024</h2>
        <div class="chart-area" id="chartC" style="height:420px;"></div>
      </section>
    </div>
  </main>

  <script>
    var COLORS = { Communicable: '#C9544D', NCD: '#2B6998', Injury: '#E6A817' };

    // === Panel A: Stacked Bar Chart (SVG) ===
    function drawPanelA() {
      var container = document.getElementById('chartA');
      var w = container.clientWidth;
      var h = container.clientHeight;

      var data1990 = [
        { cat: 'Injury', val: 253.7 },
        { cat: 'NCD', val: 768.2 },
        { cat: 'Communicable', val: 1128.4 }
      ];
      var data2024 = [
        { cat: 'Injury', val: 308.6 },
        { cat: 'NCD', val: 1487.3 },
        { cat: 'Communicable', val: 612.5 }
      ];

      var maxVal = 2408; // total 2024
      var padLeft = 60, padRight = 30, padTop = 10, padBot = 40;
      var chartW = w - padLeft - padRight;
      var chartH = h - padTop - padBot;
      var barW = 100;
      var gap = (chartW - 2 * barW) / 3;

      var textColor = '#0f172a';
      var gridColor = 'rgba(0,0,0,0.06)';
      var textSec = '#64748b';

      var svg = '<svg width="' + w + '" height="' + h + '" xmlns="http://www.w3.org/2000/svg">';

      // Y-axis gridlines
      for (var i = 0; i <= 2400; i += 400) {
        var yy = padTop + chartH - (i / maxVal) * chartH;
        svg += '<line x1="' + padLeft + '" y1="' + yy + '" x2="' + (w - padRight) + '" y2="' + yy + '" stroke="' + gridColor + '" stroke-width="1"/>';
        svg += '<text x="' + (padLeft - 8) + '" y="' + (yy + 4) + '" text-anchor="end" fill="' + textSec + '" font-family="Inter" font-size="11">' + i + '</text>';
      }

      // Y-axis label
      svg += '<text x="14" y="' + (padTop + chartH/2) + '" text-anchor="middle" fill="' + textSec + '" font-family="Inter" font-size="11" transform="rotate(-90,14,' + (padTop + chartH/2) + ')">DALYs (millions)</text>';

      // Draw stacked bars
      function drawStackedBar(data, centerX) {
        var cumY = 0;
        for (var j = 0; j < data.length; j++) {
          var barH = (data[j].val / maxVal) * chartH;
          var yy = padTop + chartH - cumY - barH;
          svg += '<rect x="' + (centerX - barW/2) + '" y="' + yy + '" width="' + barW + '" height="' + barH + '" fill="' + COLORS[data[j].cat] + '" rx="2"/>';
          // Value label inside bar if big enough
          if (barH > 22) {
            svg += '<text x="' + centerX + '" y="' + (yy + barH/2 + 4) + '" text-anchor="middle" fill="white" font-family="Inter" font-size="12" font-weight="600">' + data[j].val.toFixed(0) + 'M</text>';
          }
          cumY += barH;
        }
      }

      var x1990 = padLeft + gap + barW/2;
      var x2024 = padLeft + 2*gap + barW + barW/2 + gap/2;

      drawStackedBar(data1990, x1990);
      drawStackedBar(data2024, x2024);

      // X-axis labels
      svg += '<text x="' + x1990 + '" y="' + (padTop + chartH + 24) + '" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="600">1990</text>';
      svg += '<text x="' + x2024 + '" y="' + (padTop + chartH + 24) + '" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="600">2024</text>';

      // Total labels on top
      var total1990 = 1128.4 + 768.2 + 253.7;
      var total2024 = 612.5 + 1487.3 + 308.6;
      svg += '<text x="' + x1990 + '" y="' + (padTop + chartH - (total1990/maxVal)*chartH - 6) + '" text-anchor="middle" fill="' + textSec + '" font-family="Inter" font-size="11" font-weight="500">' + total1990.toFixed(0) + 'M total</text>';
      svg += '<text x="' + x2024 + '" y="' + (padTop + chartH - (total2024/maxVal)*chartH - 6) + '" text-anchor="middle" fill="' + textSec + '" font-family="Inter" font-size="11" font-weight="500">' + total2024.toFixed(0) + 'M total</text>';

      svg += '</svg>';
      container.innerHTML = svg;
    }

    // === Panel B: 100% Stacked Horizontal Bar Chart (SVG) ===
    function drawPanelB() {
      var container = document.getElementById('chartB');
      var w = container.clientWidth;
      var h = container.clientHeight;

      var incomeData = [
        { year: 1990, group: 'Low income', comm: 71.2, ncd: 19.8, inj: 9.0 },
        { year: 2024, group: 'Low income', comm: 52.8, ncd: 37.4, inj: 9.8 },
        { year: 1990, group: 'Lower-middle', comm: 52.4, ncd: 36.1, inj: 11.5 },
        { year: 2024, group: 'Lower-middle', comm: 27.1, ncd: 60.5, inj: 12.4 },
        { year: 1990, group: 'Upper-middle', comm: 28.7, ncd: 57.3, inj: 14.0 },
        { year: 2024, group: 'Upper-middle', comm: 11.3, ncd: 77.2, inj: 11.5 },
        { year: 1990, group: 'High income', comm: 8.3, ncd: 81.6, inj: 10.1 },
        { year: 2024, group: 'High income', comm: 4.1, ncd: 87.8, inj: 8.1 }
      ];

      var padLeft = 110, padRight = 40, padTop = 6, padBot = 32;
      var chartW = w - padLeft - padRight;
      var chartH = h - padTop - padBot;

      var barH = 26;
      var barGap = 4;
      var groupGap = 14;
      var nBars = incomeData.length;
      var totalBarsH = nBars * barH + (4-1) * groupGap + (nBars-4-1) * barGap + 3 * barGap;
      // Recalculate: 4 pairs of 2 bars, with groupGap between pairs and barGap within pairs
      totalBarsH = 4 * (2 * barH + barGap) + 3 * groupGap;

      var startYY = padTop + (chartH - totalBarsH) / 2;

      var textColor = '#0f172a';
      var gridColor = 'rgba(0,0,0,0.06)';
      var textSec = '#64748b';

      var svg = '<svg width="' + w + '" height="' + h + '" xmlns="http://www.w3.org/2000/svg">';

      // X-axis gridlines
      for (var pct = 0; pct <= 100; pct += 25) {
        var xx = padLeft + (pct / 100) * chartW;
        svg += '<line x1="' + xx + '" y1="' + padTop + '" x2="' + xx + '" y2="' + (padTop + chartH) + '" stroke="' + gridColor + '" stroke-width="1"/>';
        svg += '<text x="' + xx + '" y="' + (padTop + chartH + 16) + '" text-anchor="middle" fill="' + textSec + '" font-family="Inter" font-size="10">' + pct + '%</text>';
      }

      // Draw bars
      var currentY = startYY;
      for (var i = 0; i < 4; i++) {
        var d1990 = incomeData[i * 2];
        var d2024 = incomeData[i * 2 + 1];

        // Group label
        svg += '<text x="' + (padLeft - 8) + '" y="' + (currentY + barH + barGap/2 + 4) + '" text-anchor="end" fill="' + textColor + '" font-family="Inter" font-size="11" font-weight="500">' + d1990.group + '</text>';

        // 1990 bar
        var x = padLeft;
        var segments1990 = [
          { pct: d1990.comm, cat: 'Communicable' },
          { pct: d1990.ncd, cat: 'NCD' },
          { pct: d1990.inj, cat: 'Injury' }
        ];
        for (var s = 0; s < segments1990.length; s++) {
          var segW = (segments1990[s].pct / 100) * chartW;
          svg += '<rect x="' + x + '" y="' + currentY + '" width="' + segW + '" height="' + barH + '" fill="' + COLORS[segments1990[s].cat] + '"/>';
          if (segW > 30) {
            svg += '<text x="' + (x + segW/2) + '" y="' + (currentY + barH/2 + 4) + '" text-anchor="middle" fill="white" font-family="Inter" font-size="10" font-weight="500">' + segments1990[s].pct.toFixed(0) + '%</text>';
          }
          x += segW;
        }
        // Year label
        svg += '<text x="' + (padLeft + chartW + 6) + '" y="' + (currentY + barH/2 + 4) + '" fill="' + textSec + '" font-family="Inter" font-size="9">1990</text>';

        currentY += barH + barGap;

        // 2024 bar
        x = padLeft;
        var segments2024 = [
          { pct: d2024.comm, cat: 'Communicable' },
          { pct: d2024.ncd, cat: 'NCD' },
          { pct: d2024.inj, cat: 'Injury' }
        ];
        for (var s = 0; s < segments2024.length; s++) {
          var segW = (segments2024[s].pct / 100) * chartW;
          svg += '<rect x="' + x + '" y="' + currentY + '" width="' + segW + '" height="' + barH + '" fill="' + COLORS[segments2024[s].cat] + '"/>';
          if (segW > 30) {
            svg += '<text x="' + (x + segW/2) + '" y="' + (currentY + barH/2 + 4) + '" text-anchor="middle" fill="white" font-family="Inter" font-size="10" font-weight="500">' + segments2024[s].pct.toFixed(0) + '%</text>';
          }
          x += segW;
        }
        svg += '<text x="' + (padLeft + chartW + 6) + '" y="' + (currentY + barH/2 + 4) + '" fill="' + textSec + '" font-family="Inter" font-size="9">2024</text>';

        currentY += barH + groupGap;
      }

      // X-axis label
      svg += '<text x="' + (padLeft + chartW/2) + '" y="' + (padTop + chartH + 28) + '" text-anchor="middle" fill="' + textSec + '" font-family="Inter" font-size="11">Share of total DALYs (%)</text>';

      svg += '</svg>';
      container.innerHTML = svg;
    }

    // === Panel C: Slope/Bump Chart (SVG) ===
    function drawPanelC() {
      var container = document.getElementById('chartC');
      var w = container.clientWidth;
      var h = container.clientHeight;

      var causes1990 = [
        { rank: 1, cause: 'Lower respiratory infections', cat: 'Communicable', dalys: 178.5 },
        { rank: 2, cause: 'Diarrheal diseases', cat: 'Communicable', dalys: 155.2 },
        { rank: 3, cause: 'Neonatal preterm birth', cat: 'Communicable', dalys: 103.8 },
        { rank: 4, cause: 'Ischemic heart disease', cat: 'NCD', dalys: 98.6 },
        { rank: 5, cause: 'Stroke', cat: 'NCD', dalys: 82.4 },
        { rank: 6, cause: 'Malaria', cat: 'Communicable', dalys: 78.1 },
        { rank: 7, cause: 'Tuberculosis', cat: 'Communicable', dalys: 72.3 },
        { rank: 8, cause: 'Measles', cat: 'Communicable', dalys: 65.9 },
        { rank: 9, cause: 'COPD', cat: 'NCD', dalys: 57.2 },
        { rank: 10, cause: 'Road injuries', cat: 'Injury', dalys: 52.7 }
      ];
      var causes2024 = [
        { rank: 1, cause: 'Ischemic heart disease', cat: 'NCD', dalys: 192.3 },
        { rank: 2, cause: 'Stroke', cat: 'NCD', dalys: 147.8 },
        { rank: 3, cause: 'Diabetes mellitus', cat: 'NCD', dalys: 118.4 },
        { rank: 4, cause: 'COPD', cat: 'NCD', dalys: 105.1 },
        { rank: 5, cause: 'Neonatal preterm birth', cat: 'Communicable', dalys: 82.6 },
        { rank: 6, cause: 'Lower respiratory infections', cat: 'Communicable', dalys: 78.3 },
        { rank: 7, cause: 'Low back pain', cat: 'NCD', dalys: 74.9 },
        { rank: 8, cause: 'Depressive disorders', cat: 'NCD', dalys: 68.5 },
        { rank: 9, cause: 'Road injuries', cat: 'Injury', dalys: 63.2 },
        { rank: 10, cause: 'Lung cancer', cat: 'NCD', dalys: 58.7 }
      ];

      var map1990 = {}, map2024 = {};
      causes1990.forEach(function(c) { map1990[c.cause] = c; });
      causes2024.forEach(function(c) { map2024[c.cause] = c; });

      var padLeft = 185, padRight = 195, padTop = 22, padBot = 10;
      var chartW = w - padLeft - padRight;
      var chartH = h - padTop - padBot;

      var textColor = '#0f172a';
      var gridColor = 'rgba(0,0,0,0.05)';
      var textSec = '#64748b';

      var svg = '<svg width="' + w + '" height="' + h + '" xmlns="http://www.w3.org/2000/svg">';

      // Year labels
      svg += '<text x="' + padLeft + '" y="16" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="700">1990</text>';
      svg += '<text x="' + (padLeft + chartW) + '" y="16" text-anchor="middle" fill="' + textColor + '" font-family="Inter" font-size="14" font-weight="700">2024</text>';

      // Rank gridlines
      for (var i = 1; i <= 10; i++) {
        var yy = padTop + ((i - 1) / 9) * chartH;
        svg += '<line x1="' + padLeft + '" y1="' + yy + '" x2="' + (padLeft + chartW) + '" y2="' + yy + '" stroke="' + gridColor + '" stroke-width="1" stroke-dasharray="3,3"/>';
        svg += '<text x="' + (padLeft - 36) + '" y="' + (yy + 4) + '" text-anchor="end" fill="' + textSec + '" font-family="Inter" font-size="10">#' + i + '</text>';
        svg += '<text x="' + (padLeft + chartW + 36) + '" y="' + (yy + 4) + '" text-anchor="start" fill="' + textSec + '" font-family="Inter" font-size="10">#' + i + '</text>';
      }

      function getRankY(rank) { return padTop + ((rank - 1) / 9) * chartH; }

      // Draw EXIT causes (only in 1990) - faded
      causes1990.forEach(function(c) {
        if (!map2024[c.cause]) {
          var y1 = getRankY(c.rank);
          var col = COLORS[c.cat];
          svg += '<line x1="' + padLeft + '" y1="' + y1 + '" x2="' + (padLeft + chartW * 0.6) + '" y2="' + (y1 + (c.rank > 5 ? 15 : -15)) + '" stroke="' + col + '" stroke-width="1.5" stroke-dasharray="5,3" opacity="0.35"/>';
          svg += '<circle cx="' + padLeft + '" cy="' + y1 + '" r="4" fill="' + col + '" opacity="0.4"/>';
          svg += '<text x="' + (padLeft - 42) + '" y="' + (y1 + 4) + '" text-anchor="end" fill="' + col + '" font-family="Inter" font-size="11" opacity="0.5">' + c.cause + '</text>';
        }
      });

      // Draw ENTER causes (only in 2024) - faded
      causes2024.forEach(function(c) {
        if (!map1990[c.cause]) {
          var y2 = getRankY(c.rank);
          var col = COLORS[c.cat];
          svg += '<line x1="' + (padLeft + chartW * 0.4) + '" y1="' + (y2 + (c.rank > 5 ? 15 : -15)) + '" x2="' + (padLeft + chartW) + '" y2="' + y2 + '" stroke="' + col + '" stroke-width="1.5" stroke-dasharray="5,3" opacity="0.35"/>';
          svg += '<circle cx="' + (padLeft + chartW) + '" cy="' + y2 + '" r="4" fill="' + col + '" opacity="0.4"/>';
          svg += '<text x="' + (padLeft + chartW + 42) + '" y="' + (y2 + 4) + '" text-anchor="start" fill="' + col + '" font-family="Inter" font-size="11" opacity="0.5">' + c.cause + '</text>';
        }
      });

      // Draw CONNECTED causes - bold, prominent
      var connected = [];
      causes1990.forEach(function(c) {
        if (map2024[c.cause]) {
          var c2 = map2024[c.cause];
          connected.push({ cause: c.cause, cat: c.cat, r1: c.rank, r2: c2.rank, d1: c.dalys, d2: c2.dalys });
        }
      });

      // Sort by magnitude of rank change (draw large changes last / on top)
      connected.sort(function(a, b) { return Math.abs(a.r2 - a.r1) - Math.abs(b.r2 - a.r1); });

      connected.forEach(function(c) {
        var y1 = getRankY(c.r1);
        var y2 = getRankY(c.r2);
        var col = COLORS[c.cat];
        var change = c.r1 - c.r2; // positive = rose, negative = dropped
        var absChange = Math.abs(change);
        var lineW = Math.max(2, 2 + absChange * 0.5);
        var opacity = Math.min(1, 0.55 + absChange * 0.12);

        svg += '<line x1="' + padLeft + '" y1="' + y1 + '" x2="' + (padLeft + chartW) + '" y2="' + y2 + '" stroke="' + col + '" stroke-width="' + lineW + '" opacity="' + opacity + '"/>';

        // Dots
        svg += '<circle cx="' + padLeft + '" cy="' + y1 + '" r="5" fill="' + col + '" stroke="white" stroke-width="2"/>';
        svg += '<circle cx="' + (padLeft + chartW) + '" cy="' + y2 + '" r="5" fill="' + col + '" stroke="white" stroke-width="2"/>';

        // Left label (1990)
        svg += '<text x="' + (padLeft - 42) + '" y="' + (y1 + 4) + '" text-anchor="end" fill="' + col + '" font-family="Inter" font-size="12" font-weight="500">' + c.cause + '</text>';

        // Right label (2024) with rank change arrow
        var arrow = '';
        var arrowColor = '#059669';
        if (change > 0) { arrow = ' ↑' + change; arrowColor = '#059669'; }
        else if (change < 0) { arrow = ' ↓' + Math.abs(change); arrowColor = '#dc2626'; }

        svg += '<text x="' + (padLeft + chartW + 42) + '" y="' + (y2 + 4) + '" text-anchor="start" fill="' + col + '" font-family="Inter" font-size="12" font-weight="500">' + c.cause;
        if (arrow) {
          svg += '<tspan fill="' + arrowColor + '" font-weight="700" font-size="11">' + arrow + '</tspan>';
        }
        svg += '</text>';
      });

      svg += '</svg>';
      container.innerHTML = svg;
    }

    // Render all panels
    drawPanelA();
    drawPanelB();
    drawPanelC();
  </script>
</body>
