from PIL import Image
img = Image.open('/app/output/result.png')
w, h = img.size

# Check for our chart colors in the image
# Communicable: #C9544D = (201, 84, 77)
# NCD: #2B6998 = (43, 105, 152)
# Injury: #E6A817 = (230, 168, 23)

def is_near_color(px, target, tol=30):
    return all(abs(px[i] - target[i]) <= tol for i in range(3))

colors_found = {'Communicable': 0, 'NCD': 0, 'Injury': 0}
