for y in range(0, h, 10):
    for x in range(0, w, 10):
        px = img.getpixel((x, y))
        for name, target in targets.items():
            if is_near_color(px, target):
                colors_found[name] += 1

for name, count in colors_found.items():
    print(f'{name} (#{targets[name][0]:02X}{targets[name][1]:02X}{targets[name][2]:02X}): {count} pixel matches')
